41	const PROCESSING_FEE = 5;
42	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
43	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
44	
45	/** The MHPCO price list; only the types pinned down by tests so far. */
46	const BASE_PREMIUMS: Record<string, number | undefined> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	};
54	
55	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
56	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
57	
58	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
59	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
60	
61	const basePremiumFor = (item: Item): number => {
62	  const basePremium = BASE_PREMIUMS[item.type];
63	  if (basePremium === undefined) throw new Error(`Unknown item type: ${item.type}`);
64	  return basePremium;
65	};
66	
67	const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);
68	
69	/** A building block of 3 alike components is offered at a special base premium. */
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const alikeComponentGroups = (items: Item[]): Item[][] => [
74	  ...items
75	    .reduce(
76	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
77	      new Map<string, Item[]>(),
78	    )
79	    .values(),
80	];
81	
82	const basePremiumForGroup = (group: Item[]): number =>
83	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sum(group.map(basePremiumFor));
84	
85	const CURSE_SURCHARGE = 0.5;
86	
87	/** Item-specific surcharges are levied on the affected item's own base premium. */
88	const surchargesFor = (item: Item): number =>
89	  item.cursed ? basePremiumFor(item) * CURSE_SURCHARGE : 0;
90	
91	const quote = (step: QuoteStep): StepResult => {
92	  const policyBasePremium =
93	    sum(alikeComponentGroups(step.items).map(basePremiumForGroup)) +
94	    sum(step.items.map(surchargesFor));
95	  const afterInitialAssessment = policyBasePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
96	  return { premium: roundUpToWholeG(afterInitialAssessment + PROCESSING_FEE) };
97	};
98	
99	const runStep = (step: Step): StepResult => {
100	  if (step.op === "quote") return quote(step);
101	  throw new Error(`Unsupported step: ${step.op}`);
102	};
103	
104	export const runScenario = (scenario: Scenario): ScenarioResult => ({
105	  results: scenario.steps.map(runStep),
106	});
