const quote = (step: QuoteStep): StepResult => {
  const basePremium = sumOf(alikeComponentGroups(step.items), basePremiumForGroup);
  const surcharges = sumOf(step.items, surchargesFor);
  const afterInitialAssessment =
    (basePremium + surcharges) * (1 + INITIAL_ASSESSMENT_SURCHARGE);
  return { premium: roundUpToWholeG(afterInitialAssessment + PROCESSING_FEE) };
};
